"use client";

import CheckCircleOutlineIcon from "@mui/icons-material/CheckCircleOutline";
import { Box, Button, Paper, Stack, Typography } from "@mui/material";
import { useThemeMode } from "@/components/ThemeModeProvider";
import { ThemePreset } from "@/lib/theme";

const presetOptions: { value: ThemePreset; label: string; color: string }[] = [
  { value: "ocean", label: "Ocean Blue", color: "#0d47a1" },
  { value: "emerald", label: "Emerald Green", color: "#166534" },
  { value: "sunset", label: "Sunset Orange", color: "#c2410c" },
  { value: "violet", label: "Violet Purple", color: "#5b21b6" },
  { value: "rose", label: "Rose Red", color: "#be123c" },
  { value: "cyan", label: "Cyan Teal", color: "#0e7490" },
  { value: "amber", label: "Amber Gold", color: "#b45309" },
  { value: "slate", label: "Slate Gray", color: "#334155" },
  { value: "indigo", label: "Indigo Deep", color: "#3730a3" },
  { value: "lime", label: "Lime Green", color: "#4d7c0f" },
  { value: "vibgyorLight", label: "Light VIBGYOR", color: "#7c83fd" },
  { value: "softLight", label: "Soft Light", color: "#3b82f6" }
];

// Renders clickable theme preset cards and applies selected preset globally.
export default function ThemePalettePanel() {
  // Functional responsibility:
  // - Render selectable palette cards and apply selected theme preset globally.
  // Inputs:
  // - Reads current preset and setPreset handler from theme context.
  // Output:
  // - Theme-card grid with applied/active state feedback.
  // Failure behavior:
  // - If provider is missing, useThemeMode throws explicit context error.
  const { preset, setPreset } = useThemeMode();

  return (
    <Stack spacing={2}>
      <Typography variant="body1" color="text.secondary">
        Select a color theme for the entire website.
      </Typography>
      <Stack direction={{ xs: "column", sm: "row" }} spacing={2} flexWrap="wrap">
        {presetOptions.map((option) => {
          const selected = preset === option.value;
          return (
            <Paper
              key={option.value}
              sx={{
                p: 2,
                minWidth: 190,
                border: selected ? "2px solid" : "1px solid",
                borderColor: selected ? "primary.main" : "divider"
              }}
            >
              <Stack spacing={1.5}>
                <Box sx={{ height: 48, borderRadius: 1.5, backgroundColor: option.color }} />
                <Typography fontWeight={700}>{option.label}</Typography>
                <Button
                  variant={selected ? "contained" : "outlined"}
                  startIcon={selected ? <CheckCircleOutlineIcon /> : undefined}
                  onClick={() => setPreset(option.value)}
                >
                  {selected ? "Applied" : "Apply Theme"}
                </Button>
              </Stack>
            </Paper>
          );
        })}
      </Stack>
    </Stack>
  );
}
